    <div style="background:linear-gradient(135deg,#fd7901 0,#e66a00 100%);border-radius:14px;padding:22px;color:#fff;box-shadow:0 6px 20px rgba(253,121,1,.35),0 0 25px rgba(253,121,1,.15);border:1px solid rgba(255,255,255,.2)">
      <div style="margin-bottom:10px">
        <div style="display:inline-flex;align-items:center;gap:8px;padding:6px 12px;border-radius:999px;font-size:10px;letter-spacing:1.6px;text-transform:uppercase;font-weight:800;background:rgba(0,0,0,.15)">
          <span style="width:9px;height:9px;border-radius:50%;background:#fff;box-shadow:0 0 12px rgba(253,121,1,.4);display:inline-block"></span>TREASURE VAULT 1
        </div>
        <div style="margin-top:5px;font-size:clamp(24px,6vw,32px);font-weight:900;letter-spacing:-.5px">MINI VAULT <span style="font-size:16px;font-weight:400;opacity:.9"></span>
        </div>
