        <div style="flex:1;margin-top:4px;border-right:1px solid rgba(255,255,255,.2);text-align:center">
          <div style="font-size:9px;opacity:.7;text-transform:uppercase;margin-bottom:4px;font-weight:700">MIN DEPOSIT</div>
          <div style="font-size:11px;font-weight:900">$30-$49</div>
        </div>
          <div style="flex:1;margin-top:4px;border-right:1px solid rgba(255,255,255,.2);text-align:center">
          <div style="font-size:9px;opacity:.7;text-transform:uppercase;margin-bottom:4px;font-weight:700">RANDOM BONUS</div>
          <div style="font-size:11px;font-weight:900">$1-$19</div>
        </div>
        <div style="flex:1;margin-top:4px;border-right:1px solid rgba(255,255,255,.2);text-align:center">
          <div style="font-size:9px;opacity:.7;text-transform:uppercase;margin-bottom:4px;font-weight:700">TURNOVER</div>
          <div style="font-size:11px;font-weight:900">CREDIT HIT $200 TO WITHDRAW</div>
        </div>
        <div style="flex:1;margin-top:4px;text-align:center">
          <div style="font-size:9px;opacity:.7;text-transform:uppercase;margin-bottom:4px;font-weight:700">MAX WITHDRAW</div>
          <div style="font-size:11px;font-weight:900">$20</div>
        </div>
      </div>
    </div>
    <div style="display:flex;gap:8px;margin:10px 0 10px 0">
      <div style="flex:1;background:rgba(253,121,1,.15);border:1.5px solid #e2e8f0;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:9px;color:#fff;font-weight:800;text-transform:uppercase;margin-bottom:4px">CLAIM LIMIT</div>
        <div style="font-size:13px;font-weight:900;color:#d91e1e">UNLIMITED</div>
      </div>
      <div style="flex:1;background:#ffe8d9;border:1.5px solid #fd7901;border-radius:12px;padding:12px;text-align:center">
        <div style="font-size:9px;color:#1e293b;font-weight:800;text-transform:uppercase;margin-bottom:4px">ALLOWED GAME</div>
        <div style="font-size:13px;font-weight:900;color:#d91e1e">EVENT GAMES ONLY</div>
        <div style="font-size:9px;font-weight:900;color:#d91e1e">( EXCEPT AFBSLOT2 )</div>
        
      </div>
    </div>
    <div style="display:flex;gap:80px;margin-top:1px 0 10px 0"></div>
    <div style="background:rgba(253,121,1,.15);border:1px solid #edf2f7;border-radius:12px;padding:14px;margin-bottom:10px;box-shadow:0 2px 5px rgba(0,0,0,.03)">
      <div style="font-size:11px;color:#fff;font-weight:600;margin-bottom:8px;display:flex;align-items:center;gap:8px">
        <span style="color:#fd7901;font-size:16px">✓</span>Player name must match bank records exactly.
      </div>
      <div style="font-size:11px;color:#fff;font-weight:600;margin-bottom:8px;display:flex;align-items:center;gap:8px">
        <span style="color:#fd7901;font-size:16px">✓</span>No stacking with other bonuses.
      </div>
     <div style="font-size:11px;color:#fff;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px">
        <span style="color:#fd7901;font-size:16px">✓</span>This bonus is all you can claim.
      </div>
      <div style="font-size:11px;color:#fff;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px">
        <span style="color:#fd7901;font-size:16px">✓</span>Only slot games are permitted after deposit and before claiming this bonus. Non-slot play voids the bonus and winnings.
      </div>
      <div style="background:#fff5f5;border:1px solid #feb2b2;padding:10px;border-radius:8px;color:#c53030;font-size:11px;font-weight:900;text-align:center;letter-spacing:.2px">❌ NO SAVE OR BUY FREE GAME</div>
    </div>
    <div style="border-top:2px solid #f1f5f9;padding-top:12px">
      <div style="font-size:14px;font-weight:900;color:#fd7901;text-transform:uppercase;margin-bottom:10px">Terms & Conditions</div>
      <div style="font-size:11px;color:#fff;line-height:1.6">
        <b style="color:#c15e00">• Bonus Claim Notice:</b>Remember to claim your bonus prior to entering the game, or it will automatically be voided. <br>
        <b style="color:#c15e00">• Eligibility:</b>Account name must exactly match bank details. 1 account / 1 IP per Australian player. <br>
        <b style="color:#c15e00">• Withdrawal Timeframe:</b>Must be processed within <b>24 hours</b>. <br>
        <b style="color:#c15e00">• Restrictions:</b>
        <b>EVENT </b>games only (except AFBSLOT2  ). Any other play will results in forfeiture. <br>
        <b style="color:#c15e00">• Maximum Payout:</b>Capped at <b>$20</b>. Excess balance forfeited.
      </div>
    </div>
    <div style="margin-top:8px;text-align:left">
      <div style="border-top:2px solid #f1f5f9;padding-top:10px"></div>
      <div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:8px;display:flex;align-items:left;gap:8px">
        <span style="color:#fff;font-size:8px">General MEE88AU Terms &amp; Conditions apply. Abnormal betting activiy will result in your balance being zeroed.</span>
      </div>
    </div>
  </div>
  <p></p>
</var>
<style>
  @keyframes fadeInUp {
    0% {
      opacity: 0;
      transform: translateY(30px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes slideIn {
    0% {
      width: 0
    }

    100% {
      width: 40%
    }
  }

  div .div:hover {
    transform: translateX(10px);
    color: #7a56e0
  }

  .term:hover {
    transform: scale(1.05);
    box-shadow: 0 0 15px #d9d9d9
  }

  .term:hover .term-text {
    color: #200202;
    font-size: 1rem
  }

  .term-icon {
    animation: iconPulse 2s infinite ease-in-out
  }

  @keyframes iconPulse {
    0% {
      transform: scale(1)
    }

    50% {
      transform: scale(1.2)
    }

    100% {
      transform: scale(1)
    }
  }

  .border-animation {
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    border-radius: 30px;
    box-shadow: 0 0 20px #d9d9d9, 0 0 30px #d9d9d9 inset;
    border: 4px solid transparent;
    animation: glowingBorder 3s infinite alternate, rotateBorder 5s infinite linear
  }

  @keyframes glowingBorder {
    0% {
      box-shadow: 0 0 15px #d9d9d9, 0 0 25px #d9d9d9 inset
    }

    100% {
      box-shadow: 0 0 25px #d9d9d9, 0 0 40px #d9d9d9 inset
    }
  }

  @keyframes rotateBorder {
    0% {
      transform: rotateY(0)
    }

    100% {
      transform: rotateY(90deg)
    }
  }

  .border-animation2 {
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    border-radius: 30px;
    box-shadow: 0 0 20px #d9d9d9, 0 0 30px #d9d9d9 inset;
    border: 4px solid transparent;
    animation: glowingBorder2 3s infinite alternate, rotateBorder2 3s infinite linear
  }

  @keyframes glowingBorder2 {
    0% {
      box-shadow: 0 0 15px #d9d9d9, 0 0 25px #d9d9d9 inset
    }

    100% {
      box-shadow: 0 0 25px #d9d9d9, 0 0 40px #d9d9d9 inset
    }
  }

  @keyframes rotateBorder2 {
    0% {
      transform: rotateX(0)
    }

    100% {
      transform: rotateX(180deg)
    }
  }

  @keyframes circlePulse {

    0%,
    100% {
      transform: scale(1);
      opacity: .7
    }

    50% {
      transform: scale(1.5);
      opacity: .3
    }
  }

  @keyframes rotateHorizontal {
    0% {
      transform: rotateY(0)
    }

    100% {
      transform: rotateY(360deg)
    }
  }

  @keyframes rotateHorizontall {
    0% {
      transform: rotateY(0)
    }

    100% {
      transform: rotateY(30deg)
    }
  }

  @keyframes fadeInBackground {
    0% {
      background-position: 50% 50%;
      background-size: 80%
    }

    100% {
      background-position: 100% 50%;
      background-size: 110%
    }
  }

  @keyframes panelSlideIn {
    0% {
      opacity: 0;
      transform: translateY(50px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes fadeInDown {
    0% {
      opacity: 0;
      transform: translateY(-50px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes slideInLeft {
    0% {
      opacity: 0;
      transform: translateX(-50px)
    }

    100% {
      opacity: 1;
      transform: translateX(0)
    }
  }

  @keyframes slideInRight {
    0% {
      opacity: 0;
      transform: translateX(50px)
    }

    100% {
      opacity: 1;
      transform: translateX(0)
    }
  }

  @keyframes fadeInUp {
    0% {
      opacity: 0;
      transform: translateY(20px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes zoomIn {
    0% {
      opacity: 0;
      transform: scale(.8)
    }

    100% {
      opacity: 1;
      transform: scale(1)
    }
  }

  @keyframes bounceIn {
    0% {
      opacity: 0;
      transform: scale(.8)
    }

    50% {
      transform: scale(1.2)
    }

    100% {
      opacity: 1;
      transform: scale(1)
    }
  }

  @keyframes pulseGlow {

    0%,
    100% {
      text-shadow: 0 0 20px #8b0000, 0 0 30px #98fb98
    }

    50% {
      text-shadow: 0 0 40px #98fb98, 0 0 60px #98fb98
    }
  }

  @media (max-width:768px) {
    h1 {
      font-size: 24px
    }

    p,
    ul li {
      font-size: 14px
    }

    img {
      max-width: 300px
    }
  }

  @media (max-width:768px) {
    div[style*="max-width: 700px"] {
      max-width: 90%;
      margin: 20px auto;
      padding: 15px
    }

    h1 {
      font-size: 24px !important
    }

    marquee {
      font-size: 18px !important
    }

    p {
      font-size: 18px !important
    }

    table td {
      padding: 10px !important;
      font-size: 16px !important
    }

    .div {
      font-size: 16px !important;
      padding-left: 15px !important
    }

    div[style*="position: absolute"] {
      width: 120px !important;
      height: 120px !important;
      top: -60px !important;
      left: -60px !important;
      right: -60px !important
    }
  }

  @media (max-width:480px) {
    h1 {
      font-size: 20px !important
    }

    marquee {
      font-size: 16px !important
    }

    p {
      font-size: 16px !important
    }

    table td {
      font-size: 14px !important
    }

    .div {
      font-size: 14px !important
    }

    div[style*="position: absolute"] {
      width: 100px !important;
      height: 100px !important;
      top: -50px !important;
      left: -50px !important;
      right: -50px !important
    }
  }

  td:hover {
    transform: scale(1.1) rotateY(15deg) translateZ(20px);
    box-shadow: 0 20px 50px rgba(192, 0, 255, .9);
    filter: brightness(1.3)
  }

  td:hover>div {
    opacity: 1
  }

  div:hover>div {
    opacity: 1
  }

  td {
    cursor: pointer
  }

  td:hover {
    animation: neonPulse 1s infinite
  }

  @media (min-width:768px) {
    div {
      perspective: 1000px
    }

    td {
      transform-style: preserve-3d;
      transition: transform .5s ease
    }

    td:hover {
      transform: translateZ(30px)
    }
  }
</style>","DescQuillEditor":{"ops":[{"insert":"
